/**
 * DEMO ONLY: mock recovery-plan adapter.
 *
 * Returns a fixed draft generated by ai-service's real assembly code from
 * SYNTHETIC data with a mock AI narrative (see mockDraft.json). No network
 * request, no AI model call, nothing stored. Regenerate the JSON with:
 *   (cd packages/ai-service && node examples/recoveryPlanMock.ts --json) > packages/web/src/recoveryPlan/mockDraft.json
 */
import mockDraftJson from './mockDraft.json';
import type { GenerateDraftResult, RecoveryPlanApi, RecoveryPlanDraft } from './types';

export const MOCK_DISASTER_ID = 'EV-2026-014';

export interface MockRecoveryPlanApiOptions {
  /** Simulated generation time. */
  delayMs?: number;
  /** Return true to make the next generation fail (demo of the error state). */
  shouldFail?: () => boolean;
}

export function createMockRecoveryPlanApi({
  delayMs = 800,
  shouldFail = () => false,
}: MockRecoveryPlanApiOptions = {}): RecoveryPlanApi {
  let counter = 0;

  return {
    isMock: true,
    generateDraft(disasterId: string, { signal }: { signal?: AbortSignal } = {}): Promise<GenerateDraftResult> {
      return new Promise((resolve, reject) => {
        const aborted = () => reject(new DOMException('Draft generation was cancelled.', 'AbortError'));
        if (signal?.aborted) {
          aborted();
          return;
        }
        let timer: ReturnType<typeof setTimeout> | undefined;
        const onAbort = () => {
          clearTimeout(timer);
          aborted();
        };
        signal?.addEventListener('abort', onAbort, { once: true });

        timer = setTimeout(() => {
          signal?.removeEventListener('abort', onAbort);
          if (shouldFail()) {
            reject(new Error('Simulated failure: the mock AI service did not return a draft.'));
            return;
          }
          if (disasterId !== MOCK_DISASTER_ID) {
            reject(new Error(`The demo only has synthetic data for ${MOCK_DISASTER_ID}.`));
            return;
          }
          counter += 1;
          resolve({
            draftId: `mock-draft-${counter}`,
            // A fresh copy each time, so a discarded draft can't leak into the next one.
            draft: JSON.parse(JSON.stringify(mockDraftJson)) as RecoveryPlanDraft,
            promptVersion: 'irp-narrative-v1',
          });
        }, delayMs);
      });
    },
  };
}
